with with_dims as (select a.id, a.order_id, a.product_id, a.unit_price, p.channel, p.status, p.shipping_fee from order_items a left join orders p on a.order_id = p.id), enriched as (select e.*, p.stock_qty, p.category, p.cost from with_dims e left join products p on e.product_id = p.id), scored as (select *, last_value(status) ignore nulls over (partition by category order by unit_price, id rows between unbounded preceding and current row) as last_known_status, avg(shipping_fee) over (partition by status order by cost, id rows between 6 preceding and 1 preceding) as shipping_fee_avg_6_prior, ntile(5) over w_recent as unit_price_bucket, sum(shipping_fee) over (partition by channel order by stock_qty, id rows between unbounded preceding and current row) as cumulative_shipping_fee from enriched window w_recent as (partition by order_id order by unit_price, id)), enriched_order_items as (select id, order_id, unit_price, channel, shipping_fee, stock_qty, cost, last_known_status, unit_price_bucket, lag(cumulative_shipping_fee) over w_part as prev_cumulative_shipping_fee, lead(cumulative_shipping_fee) over w_part as next_cumulative_shipping_fee, lead(unit_price) over w_part as next_unit_price, row_number() over w_part as row_seq from scored where unit_price > 200 window w_part as (partition by channel order by cumulative_shipping_fee, id)) select p.channel as order_channel, e.channel as order_item_channel, count(*) as num_rows, min(e.row_seq) as min_row_seq, grouping_id() as grouping_level from enriched_order_items e left join orders p on e.order_id = p.id group by grouping sets ((p.channel, e.channel), (p.channel)) order by num_rows desc nulls first;
